Plan:
1. Read sheet A values and find the first P cell containing “Yes” or “NA”.
2. Search upward in column L for 100, take the matching F date; if no P match, use A!F3.
3. If A!F1 matches any B column C entry, write the date into B!F4.

```python
import shutil
import openpyxl
from datetime import datetime, date

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

def norm_text(v):
    if v is None:
        return ""
    return str(v).strip()

def is_yes_or_na(v):
    s = norm_text(v).lower()
    return s == "yes" or s == "na"

def is_100(v):
    if isinstance(v, bool):
        return False
    if isinstance(v, (int, float)):
        return v == 100
    s = norm_text(v)
    if not s:
        return False
    try:
        return float(s) == 100
    except Exception:
        return False

def to_date(v):
    if isinstance(v, datetime):
        return v
    if isinstance(v, date):
        return datetime(v.year, v.month, v.day)
    if isinstance(v, (int, float)) and not isinstance(v, bool):
        try:
            return datetime(1899, 12, 30) + __import__("datetime").timedelta(days=float(v))
        except Exception:
            return v
    if isinstance(v, str):
        s = v.strip()
        for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d", "%m/%d/%Y", "%d/%m/%Y"):
            try:
                return datetime.strptime(s, fmt)
            except Exception:
                pass
    return v

va = vals["A"]
vb = vals["B"]

# Find first Yes/NA in column P of A
p_row = None
for r in range(1, va.max_row + 1):
    if is_yes_or_na(va.cell(row=r, column=16).value):
        p_row = r
        break

# If found, search upward in column L for 100
date_val = None
if p_row is not None:
    for r in range(p_row - 1, 0, -1):
        if is_100(va.cell(row=r, column=12).value):
            date_val = to_date(va.cell(row=r, column=6).value)
            break

# Fallback: use A!F3
if date_val is None:
    date_val = to_date(va.cell(row=3, column=6).value)

# Check A!F1 against B column C
f1 = norm_text(va.cell(row=1, column=6).value)
match = False
for r in range(1, vb.max_row + 1):
    if norm_text(vb.cell(row=r, column=3).value) == f1:
        match = True
        break

ws = wb["B"]
if match:
    ws["F4"] = date_val
else:
    ws["F4"] = None

wb.active = wb["A"]
wb.save(OUT)

print("p_row:", p_row)
print("date_val:", date_val)
print("match:", match)
print("F4:", ws["F4"].value)
```

